export default function SchoolChallengeSection() {
  return (
    <section style={{
      position:   "relative",
      width:      "100%",
      background: "#FFFFFF",
      overflow:   "hidden",
      fontFamily: "'Plus Jakarta Sans', sans-serif",
    }}>

      {/* ── BG pattern — left page edge, shifted slightly up ── */}
      <div style={{
        position: "absolute", left: 0, top: -40,
        width: 933, height: 825,
        pointerEvents: "none", zIndex: 0,
      }}>
        <img src={r(bgImgSrc)} alt="" aria-hidden="true"
             style={{ width: "100%", height: "100%" }} />
      </div>

      {/* ── Centered 1280 content container ── */}
      {/* overflow:visible so waves can bleed to page edges */}
      <div style={{
        position: "relative",
        maxWidth:  1280,
        margin:    "0 auto",
        minHeight: 1842,
        overflow:  "visible",
      }}>

        {/* Glow ellipses */}
        <div style={{ position:"absolute", left:-72,  top:217,  width:359, height:535, borderRadius:"50%", background:"linear-gradient(175.97deg,#F4BC37 35.44%,#EC5F3D 101.05%)", opacity:0.5, filter:"blur(100px)", transform:"matrix(1,0,0,-1,0,0)", pointerEvents:"none", zIndex:0 }} />
        <div style={{ position:"absolute", left:997,  top:92,   width:359, height:535, borderRadius:"50%", background:"linear-gradient(175.97deg,#F4BC37 35.44%,#EC5F3D 101.05%)", opacity:0.5, filter:"blur(100px)", pointerEvents:"none", zIndex:0 }} />
        <div style={{ position:"absolute", left:465,  top:1080, width:359, height:535, borderRadius:"50%", background:"linear-gradient(175.97deg,#F4BC37 35.44%,#EC5F3D 101.05%)", opacity:0.5, filter:"blur(100px)", pointerEvents:"none", zIndex:0 }} />

        {/* ══════════════════════════════════════
            SECTION 1 — The challenge isn't intent
        ══════════════════════════════════════ */}

        <h2 style={{
          position:"absolute", left:40, top:124, width:900, margin:0,
          fontWeight:700, fontSize:48, lineHeight:"60px",
          letterSpacing:"-0.02em", color:"#333333", zIndex:2,
        }}>
          The challenge isn&apos;t intent.{" "}
          <span style={{ color:"#FF8B13" }}>It&apos;s execution.</span>
        </h2>

        {/* ── Orange waves at exact Figma positions (within 1280 container)
             overflow:visible on container lets them bleed to page edges ── */}

        {/* Vector 679: left:0.5, top:361 — bleeds LEFT off container → page edge */}
        <div style={{ position:"absolute", left:0.5, top:361, pointerEvents:"none", zIndex:1 }}>
          <Wave1 />
        </div>
        {/* Vector 680: left:704, top:360 */}
        <div style={{ position:"absolute", left:704, top:360, pointerEvents:"none", zIndex:1 }}>
          <Wave2 />
        </div>
        {/* Vector 681: left:1012, top:347 — bleeds RIGHT off container → page edge */}
        <div style={{ position:"absolute", left:1012, top:347, pointerEvents:"none", zIndex:1 }}>
          <Wave3 />
        </div>

        {/* Cards row — zIndex:2 sits above waves */}
        <div style={{
          position:"absolute", left:320, top:224,
          width:847, height:399,
          display:"flex", flexDirection:"row", alignItems:"center", gap:40,
          zIndex:2,
        }}>
          {/* Blue card */}
          <div style={{
            position:"relative", width:416, height:399, flexShrink:0,
            borderRadius:16, overflow:"hidden", background:"#2C3D68",
          }}>
            <img src={r(studentGirlSrc)} alt="Student" style={{
              position:"absolute", left:0, top:0,
              width:"58%", height:"100%",
              objectFit:"cover", objectPosition:"center top",
              borderRadius:"16px 0 0 16px",
            }} />
            <div style={{
              position:"absolute", inset:0, borderRadius:16,
              background:"linear-gradient(to right, transparent 38%, #2C3D68 60%)",
            }} />
            <p style={{
              position:"absolute", left:243, bottom:32, width:157, margin:0,
              fontWeight:600, fontSize:20, lineHeight:"32px", color:"#FFFFFF",
            }}>
              Teachers are already overloaded
            </p>
          </div>

          {/* Green card */}
          <div style={{
            width:164, height:255, flexShrink:0,
            borderRadius:16, background:"#38A077",
            display:"flex", alignItems:"flex-end",
            padding:16, boxSizing:"border-box",
          }}>
            <p style={{ margin:0, fontWeight:600, fontSize:20, lineHeight:"32px", color:"#FFFFFF" }}>
              Timetables are packed
            </p>
          </div>

          {/* Red card */}
          <div style={{
            width:187, height:255, flexShrink:0,
            borderRadius:16, background:"#EE5F3D",
            display:"flex", alignItems:"flex-end",
            padding:16, boxSizing:"border-box",
          }}>
            <p style={{ margin:0, fontWeight:600, fontSize:20, lineHeight:"32px", color:"#FFFFFF" }}>
              New initiatives often disrupt academics
            </p>
          </div>
        </div>

        {/* ── Rectangle 2563: "Any solution..." quote box
            Figma: left:107, top:653, w:1173, h:120,
            opacity:0.25, border:1px solid #333333 ── */}
        <div style={{
          position:"absolute", left:85, top:653,
          width:1200, height:120, boxSizing:"border-box",
          border:"1px solid #333333",
          borderRadius:8,
          opacity:0.25,
          zIndex:2,
          pointerEvents:"none",
        }} />
        {/* Text: Figma left:124, top:689, width:660 — wraps after "how" */}
        <p style={{
          position:"absolute", left:90, top:689,
          width:660, margin:0,
          fontWeight:700, fontSize:30, lineHeight:"38px",
          letterSpacing:"-0.02em", color:"#333333",
          zIndex:3,
        }}>
          Any solution that works must respect how schools actually function.
        </p>

        {/* ── Vector 678: LimitationsSwoosh
            starts below "how" (~x:659, y:700)
            shifted right so its tip ends exactly at "They" text (~x:900) ── */}
        <div style={{
          position:"absolute", left:650, top:760,
          width:247, height:75,
          pointerEvents:"none", zIndex:2,
        }}>
          <LimitationsSwoosh />
        </div>

        {/* ── Rectangle 2557: border frame
            Figma: left:864, top:771, w:416, h:94 ── */}
        <div style={{
          position:"absolute", left:864, top:771,
          width:416, height:94, boxSizing:"border-box",
          border:"1px solid #6B6868",
          opacity:0.25,
          zIndex:2,
          pointerEvents:"none",
        }} />

        {/* ── "They get our limitations." — single line, centred in rect ── */}
        <p style={{
          position:"absolute",
          left:864, top:800,
          width:416,
          margin:0,
          fontFamily:"'Caveat', cursive",
          fontWeight:700, fontSize:28, lineHeight:"38px",
          textAlign:"center",
          color:"#FF8B13",
          whiteSpace:"nowrap",
          zIndex:3,
        }}>
          They get our limitations.
        </p>

        {/* ══════════════════════════════════════
            SECTION 2 — Designed to work with your school
        ══════════════════════════════════════ */}

        <h2 style={{
          position:"absolute", left:40, top:919, width:784, margin:0,
          fontWeight:700, fontSize:48, lineHeight:"60px",
          letterSpacing:"-0.02em", color:"#333333", zIndex:2,
        }}>
          Designed to work with your school –{" "}
          <span style={{ color:"#FF8B13" }}>not around it</span>
        </h2>

        {/* Image + feature cards row */}
        <div style={{
          position:"absolute", left:"50%", transform:"translateX(calc(-50% - 5px))",
          top:1105, width:1190, height:540,
          display:"flex", flexDirection:"row", alignItems:"center", gap:24,
          zIndex:2,
        }}>
          {/* Classroom image card */}
          <div style={{
            width:540, height:540, flexShrink:0,
            background:"#FFF7F1", borderRadius:16,
            overflow:"hidden", position:"relative",
          }}>
            <img src={r(classImgSrc)} alt="Classroom session" style={{
              position:"absolute", left:"50%", transform:"translateX(-50%)",
              top:-46, width:632, height:632, objectFit:"cover",
            }} />
          </div>

          {/* Feature cards */}
          <div style={{ flex:1, height:540, display:"flex", flexDirection:"column", gap:16 }}>
            {FEATURE_CARDS.map((fc, i) => (
              <div key={i} style={{
                flex:1, background:"#FFF7F1",
                border: fc.highlighted ? "2px solid #FF8B13" : "2px solid transparent",
                borderRadius:16, padding:"16px 24px",
                display:"flex", alignItems:"center", gap:16,
                boxSizing:"border-box",
              }}>
                <div style={{
                  width:56, height:56, flexShrink:0,
                  background:"#FF8B13", borderRadius:28,
                  display:"flex", alignItems:"center", justifyContent:"center",
                }}>
                  {fc.icon}
                </div>
                <div style={{ display:"flex", flexDirection:"column", gap:4 }}>
                  <p style={{ margin:0, fontWeight:800, fontSize:30, lineHeight:"38px", letterSpacing:"-0.02em", color:"#333333", textTransform:"capitalize" }}>
                    {fc.title}
                  </p>
                  <p style={{ margin:0, fontWeight:700, fontSize:18, lineHeight:"23px", color:"#666666" }}>
                    {fc.sub}
                  </p>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* ── Rectangle 2564: bottom border box
            Figma: left:0, top:1675, w:511, h:120, opacity:0.25, border:1px solid #333 ── */}
        <div style={{
          position:"absolute", left:0, top:1675,
          width:511, height:120, boxSizing:"border-box",
          border:"1px solid rgba(51,51,51,0.25)", opacity:0.25,
        }} />

        {/* "This feels implementable." */}
        <p style={{
          position:"absolute", left:124, top:1716, width:660, margin:0,
          fontWeight:700, fontSize:30, lineHeight:"38px",
          letterSpacing:"-0.02em", color:"#333333", zIndex:2,
        }}>
          This feels implementable.
        </p>

      </div>
    </section>
  );
}